#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


set -E

DEFAULT_PROJECT="project-47b72bb7-ba90-42c9-910"
DEFAULT_ZONE="us-west1-b"
DEFAULT_INSTANCE="epm-h02-host"
DEFAULT_CANARY_SLUG="demo-a"
DEFAULT_DOMAIN="epmdemo.xyz"

AGENT_BUNDLE_DIR="/private/tmp/epm-agent-bundle"
BUILD_DIR="/private/tmp/epm-build"
CONTEXTS_ARCHIVE="/private/tmp/epm-contexts.tar.gz"

HOST_SERVICES=(
  epm-h03-identity.service
  epm-gateway.service
  epm-tunnel.service
  epm-backup-proxy.service
  epm-host-guardian.service
  google-cloud-ops-agent.service
)

die() { printf '\nStopped: %s\n' "$*" >&2; exit 1; }
need() { command -v "$1" >/dev/null 2>&1 || die "Required command missing: $1"; }
valid_gcp_ident() { [[ "$1" =~ ^[a-z0-9][a-z0-9-]*$ ]]; }
valid_release_tag() { [[ "$1" =~ ^pilot0-[0-9]{8}-[a-z0-9][a-z0-9._-]*$ ]]; }
valid_slug() { [[ "$1" =~ ^[a-z0-9][a-z0-9-]*$ ]]; }
valid_domain() { [[ "$1" =~ ^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$ ]]; }
valid_sha256_hex() { [[ "$1" =~ ^[0-9a-f]{64}$ ]]; }
valid_image_ref() {
  [[ "$1" =~ ^(sha256:[0-9a-f]{64}|epm-pilot0-(operator|admin):[a-z0-9][a-z0-9._-]*)$ ]]
}
valid_operator_id() { [[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ ]]; }

require_private_tmp_path() {
  local path="$1"
  [[ -n "$path" ]] || die "Empty temporary path."
  if [[ "$path" == /tmp || "$path" == /tmp/* ]]; then
    die "On macOS, /tmp is a symlink to /private/tmp; use /private/tmp/... instead of $path."
  fi
}

resolve_python() {
  local candidate="${EPM_PYTHON:-$application/.venv/bin/python}"
  if [[ ! -x "$candidate" ]]; then
    candidate="$repo/.venv/easy-property-management/bin/python"
  fi
  [[ -x "$candidate" ]] || die "Python interpreter not found. Set EPM_PYTHON or create application/.venv."
  printf '%s\n' "$candidate"
}

failed() {
  printf '\nRollout wizard failed (exit %s). No automatic rollback was performed.\n' "$1" >&2
  if [[ -n "${snapshot_file:-}" && -f "${snapshot_file:-}" ]]; then
    printf 'Pre-rollout snapshot preserved at: %s\n' "$snapshot_file" >&2
    printf 'Inspect host state or run rollback with:\n' >&2
    printf '  bash application/scripts/epm-pilot0-rollout.sh rollback\n' >&2
  fi
}

vm_ssh() {
  gcloud compute ssh "$EPM_INSTANCE" \
    --project="$EPM_PROJECT" \
    --zone="$EPM_ZONE" \
    --tunnel-through-iap \
    "$@"
}

vm_scp_to() {
  local src="$1" dst="$2"
  gcloud compute scp "$src" "$EPM_INSTANCE:$dst" \
    --project="$EPM_PROJECT" \
    --zone="$EPM_ZONE" \
    --tunnel-through-iap
}

# Runs a Python script read from stdin on the GCP host as root, preferring
# /opt/epm/python/bin/python3 (Python 3.14) over system python3.
vm_python() {
  local arg remote_args=""
  for arg; do
    remote_args+=" $(printf '%q' "$arg")"
  done
  vm_ssh --command="sudo bash -c 'PY=/opt/epm/python/bin/python3; [ -x \"\$PY\" ] || PY=python3; exec \"\$PY\" - \"\$@\"' _${remote_args}"
}

valid_slug_list() {
  local raw="$1" slug
  [[ "$raw" == "ALL" ]] && return 0
  [[ -n "$raw" ]] || return 1
  local IFS=','
  for slug in $raw; do
    valid_slug "$slug" || return 1
  done
}

select_gcp_target() {
  ask EPM_PROJECT "GCP project ID [blank: $DEFAULT_PROJECT]:"
  EPM_PROJECT="${EPM_PROJECT:-$DEFAULT_PROJECT}"
  ask EPM_ZONE "GCP zone [blank: $DEFAULT_ZONE]:"
  EPM_ZONE="${EPM_ZONE:-$DEFAULT_ZONE}"
  ask EPM_INSTANCE "GCP VM instance [blank: $DEFAULT_INSTANCE]:"
  EPM_INSTANCE="${EPM_INSTANCE:-$DEFAULT_INSTANCE}"
  valid_gcp_ident "$EPM_PROJECT" || die "Invalid GCP project ID: $EPM_PROJECT"
  valid_gcp_ident "$EPM_ZONE" || die "Invalid GCP zone: $EPM_ZONE"
  valid_gcp_ident "$EPM_INSTANCE" || die "Invalid GCP instance: $EPM_INSTANCE"
  write_env EPM_PROJECT "$EPM_PROJECT"
  write_env EPM_ZONE "$EPM_ZONE"
  write_env EPM_INSTANCE "$EPM_INSTANCE"
}

verify_contexts_archive() {
  local archive="$1"
  [[ -f "$archive" && ! -L "$archive" ]] || die "Contexts archive missing: $archive"
  "$python_path" - "$archive" <<'PY'
import sys, tarfile
from pathlib import PurePosixPath

with tarfile.open(sys.argv[1], "r:gz") as archive:
    names = set()
    for member in archive.getmembers():
        path = PurePosixPath(member.name)
        if path.is_absolute() or ".." in path.parts:
            raise SystemExit(f"Unsafe archive entry: {member.name}")
        if not (member.isfile() or member.isdir()):
            raise SystemExit(f"Unsupported archive entry type: {member.name}")
        if any(p.startswith("._") or p in {".DS_Store", "__pycache__"} for p in path.parts):
            raise SystemExit(f"macOS metadata or cache found in archive: {member.name}")
        if member.isfile():
            names.add(str(path))

required = {
    "operator/Dockerfile",
    "operator/dependencies.lock",
    "operator/resources/hosted-candidate.json",
    "admin/Dockerfile",
    "admin/dependencies.lock",
    "admin/resources/hosted-candidate.json",
}
missing = sorted(required - names)
if missing:
    raise SystemExit(f"Incomplete contexts archive; missing: {', '.join(missing)}")
PY
}

fetch_agent_bundle() {
  require_private_tmp_path "$AGENT_BUNDLE_DIR"
  local refresh=true
  if [[ -f "$AGENT_BUNDLE_DIR/dependencies.lock" && -d "$AGENT_BUNDLE_DIR/wheelhouse" ]]; then
    local wheel_count
    wheel_count="$(find "$AGENT_BUNDLE_DIR/wheelhouse" -maxdepth 1 -name '*.whl' | wc -l | tr -d ' ')"
    say "Cached bundle found at $AGENT_BUNDLE_DIR ($wheel_count wheels)."
    if ! confirm "Re-fetch dependencies.lock and wheelhouse from $EPM_INSTANCE?"; then
      refresh=false
    fi
  fi
  if [[ "$refresh" == true ]]; then
    local staging
    staging="$(mktemp -d /private/tmp/epm-agent-bundle-stage.XXXXXXXX)"
    say "Fetching /opt/epm/agent-bundle/{dependencies.lock,wheelhouse} via IAP..."
    vm_ssh --command='sudo tar -C /opt/epm/agent-bundle -cf - dependencies.lock wheelhouse' \
      | tar -C "$staging" -xf -
    [[ -f "$staging/dependencies.lock" && -d "$staging/wheelhouse" ]] ||
      die "Fetched bundle is missing dependencies.lock or wheelhouse."
    rm -rf "$AGENT_BUNDLE_DIR"
    mv "$staging" "$AGENT_BUNDLE_DIR"
  fi
  [[ -f "$AGENT_BUNDLE_DIR/dependencies.lock" && -d "$AGENT_BUNDLE_DIR/wheelhouse" ]] ||
    die "Missing pinned lockfile or wheelhouse at $AGENT_BUNDLE_DIR."
  say "Using pinned lockfile: $AGENT_BUNDLE_DIR/dependencies.lock"
}

package_and_upload_contexts() {
  require_private_tmp_path "$AGENT_BUNDLE_DIR"
  require_private_tmp_path "$BUILD_DIR"
  require_private_tmp_path "$CONTEXTS_ARCHIVE"

  say "Building frontend bundles (operator, admin, central) and packaging AMD64 contexts..."
  (
    cd "$application"
    npm run build && npm run build:admin && npm run build:central
    rm -rf "$BUILD_DIR"
    mkdir -p "$BUILD_DIR"
    PYTHONPATH="apps/server:." "$python_path" scripts/hosted_package.py \
      --component operator --architecture amd64 \
      --lock "$AGENT_BUNDLE_DIR/dependencies.lock" \
      --wheelhouse "$AGENT_BUNDLE_DIR/wheelhouse" \
      --output "$BUILD_DIR/operator"
    PYTHONPATH="apps/server:." "$python_path" scripts/hosted_package.py \
      --component admin --identity --architecture amd64 \
      --lock "$AGENT_BUNDLE_DIR/dependencies.lock" \
      --wheelhouse "$AGENT_BUNDLE_DIR/wheelhouse" \
      --output "$BUILD_DIR/admin"
  )

  rm -f "$CONTEXTS_ARCHIVE"
  COPYFILE_DISABLE=1 tar --no-xattrs --exclude='._*' --exclude='.DS_Store' \
    -C "$BUILD_DIR" -czf "$CONTEXTS_ARCHIVE" operator admin
  verify_contexts_archive "$CONTEXTS_ARCHIVE"

  local digest
  digest="$(shasum -a 256 "$CONTEXTS_ARCHIVE")"
  digest="${digest%% *}"
  say "Archive verified (zero AppleDouble sidecars). SHA-256: $digest"
  write_env EPM_CONTEXTS_SHA256 "$digest"

  confirm "Upload $CONTEXTS_ARCHIVE to $EPM_INSTANCE:/tmp/epm-contexts.tar.gz via IAP?" ||
    die "Upload cancelled."
  vm_scp_to "$CONTEXTS_ARCHIVE" "/tmp/epm-contexts.tar.gz"
  say "Uploaded contexts archive to $EPM_INSTANCE:/tmp/epm-contexts.tar.gz."
}

build_remote_images() {
  valid_release_tag "$EPM_RELEASE_TAG" || die "Invalid release tag: $EPM_RELEASE_TAG"
  say "Building offline AMD64 OCI images on $EPM_INSTANCE for tag: $EPM_RELEASE_TAG"
  local log_file op_id admin_id
  log_file="$(mktemp /private/tmp/epm-build-remote.XXXXXXXX)"
  vm_ssh --command="
set -euo pipefail
rm -rf /tmp/build && mkdir -p /tmp/build
tar -C /tmp/build -xzf /tmp/epm-contexts.tar.gz
sudo docker buildx build --platform linux/amd64 --network=none --provenance=false \
  --load -t epm-pilot0-operator:${EPM_RELEASE_TAG} /tmp/build/operator
sudo docker buildx build --platform linux/amd64 --network=none --provenance=false \
  --load -t epm-pilot0-admin:${EPM_RELEASE_TAG} /tmp/build/admin
printf 'EPM_IMG_OPERATOR=%s\n' \"\$(sudo docker image inspect --format '{{.Id}}' epm-pilot0-operator:${EPM_RELEASE_TAG})\"
printf 'EPM_IMG_ADMIN=%s\n' \"\$(sudo docker image inspect --format '{{.Id}}' epm-pilot0-admin:${EPM_RELEASE_TAG})\"
sudo docker image inspect --format '{{.RepoTags}} {{.Id}}' \
  epm-pilot0-operator:${EPM_RELEASE_TAG} epm-pilot0-admin:${EPM_RELEASE_TAG}
" | tee "$log_file"
  op_id="$(sed -n 's/^EPM_IMG_OPERATOR=//p' "$log_file" | tail -n1)"
  admin_id="$(sed -n 's/^EPM_IMG_ADMIN=//p' "$log_file" | tail -n1)"
  rm -f "$log_file"
  valid_image_ref "$op_id" || die "Failed to capture Operator image ID from build output."
  valid_image_ref "$admin_id" || die "Failed to capture Admin image ID from build output."
  EPM_OPERATOR_IMAGE_ID="$op_id"
  EPM_ADMIN_IMAGE_ID="$admin_id"
  write_env EPM_OPERATOR_IMAGE_ID "$EPM_OPERATOR_IMAGE_ID"
  write_env EPM_ADMIN_IMAGE_ID "$EPM_ADMIN_IMAGE_ID"
  say "Operator image ID: $EPM_OPERATOR_IMAGE_ID"
  say "Admin image ID:    $EPM_ADMIN_IMAGE_ID"
}

capture_pre_rollout_snapshot() {
  local target_file="$1"
  local snapshot_json
  snapshot_json="$(vm_python <<'PY'
import json, re, subprocess
from pathlib import Path

registry_path = Path("/etc/epm/pilot0-operators/registry.json")
registry = json.loads(registry_path.read_text(encoding="utf-8"))
operators = {}
for op_id, op in sorted(registry.get("operators", {}).items()):
    slug = op["workspace_slug"]
    ctr = f"epm-op-{slug}"
    proc = subprocess.run(
        ["docker", "inspect", "--format", "{{.Image}}|{{.Config.Image}}|{{.State.Status}}", ctr],
        capture_output=True, text=True, check=False,
    )
    if proc.returncode == 0:
        parts = proc.stdout.strip().split("|", 2)
        image_id, image_ref, status = (parts + ["", "", ""])[:3]
    else:
        image_id, image_ref, status = "", "", "missing"
    operators[op_id] = {
        "operator_id": op_id,
        "workspace_slug": slug,
        "ip": op["ip"],
        "container": ctr,
        "image_id": image_id,
        "image_ref": image_ref,
        "status": status,
    }

identity_path = Path("/opt/epm/h0312/run_identity.py")
manifest = ""
if identity_path.is_file():
    match = re.search(r'^MANIFEST = "([0-9a-f]{64})"$', identity_path.read_text(encoding="utf-8"), flags=re.M)
    if match:
        manifest = match.group(1)

print(json.dumps({"admin_manifest": manifest, "operators": operators}, indent=2, sort_keys=True))
PY
)"
  printf '%s\n' "$snapshot_json" > "$target_file"
  chmod 600 "$target_file"
  write_env EPM_LAST_SNAPSHOT "$target_file"
  "$python_path" - "$target_file" <<'PY'
import json, sys
from pathlib import Path

data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
print(f"  Current Admin MANIFEST: {data.get('admin_manifest') or '(unknown)'}")
print("  Registered Pilot 0 operators:")
for op in sorted(data.get("operators", {}).values(), key=lambda x: x["workspace_slug"]):
    img = op["image_ref"] or op["image_id"] or "(none)"
    print(f"    - {op['workspace_slug']} ({op['operator_id']}, {op['ip']}): {op['status']} · {img}")
PY
}

