reinit_operator_workspace() {
  local op_id="$1" slug="$2" mode="$3" image_ref="$4"
  valid_operator_id "$op_id" || die "Invalid operator_id: $op_id"
  valid_slug "$slug" || die "Invalid workspace slug: $slug"
  valid_image_ref "$image_ref" || die "Invalid image ref: $image_ref"
  [[ "$mode" == "demo" || "$mode" == "empty" ]] || die "Invalid reinit mode: $mode"

  say "Reinitializing $slug ($op_id) in $mode mode using $image_ref..."
  vm_python "$op_id" "$slug" "$mode" "$image_ref" <<'PY'
import datetime, json, os, shutil, sqlite3, subprocess, sys
from pathlib import Path

op_id, slug, mode, image_ref = sys.argv[1:5]
ctr_name = f"epm-op-{slug}"
ws_parent = Path(f"/srv/epm/data/workspace/{op_id}")
scratch_parent = Path(f"/srv/epm/data/scratch/{op_id}")
active_dir = ws_parent / "active"
ws_json_path = active_dir / "workspace.json"

if not ws_json_path.is_file():
    raise SystemExit(f"Missing existing workspace.json at {ws_json_path}; cannot preserve workspaceId.")

original_ws_id = json.loads(ws_json_path.read_text(encoding="utf-8")).get("workspaceId")
if not original_ws_id:
    raise SystemExit(f"Empty workspaceId in {ws_json_path}; refusing to reinitialize.")

print(f"Stopping {ctr_name}...")
subprocess.run(["docker", "stop", ctr_name], check=False)

stamp = datetime.datetime.now(datetime.UTC).strftime("%Y%m%d")
backup_dir = ws_parent / f"active.bak-{stamp}"
if backup_dir.exists():
    stamp_full = datetime.datetime.now(datetime.UTC).strftime("%Y%m%d-%H%M%S")
    backup_dir = ws_parent / f"active.bak-{stamp_full}"
if backup_dir.exists():
    raise SystemExit(f"Backup destination already exists: {backup_dir}")

print(f"Backing up {active_dir} -> {backup_dir}")
active_dir.rename(backup_dir)

active_dir.mkdir(mode=0o700)
os.chown(active_dir, 65532, 65532)
scratch_reinit = f"reinit-{datetime.datetime.now(datetime.UTC).strftime('%Y%m%dT%H%M%SZ')}"

docker_cmd = [
    "docker", "run", "--rm", "--network", "none", "--read-only",
    "--cap-drop", "ALL", "--security-opt", "no-new-privileges",
    "--user", "65532:65532",
    "--tmpfs", "/tmp:rw,nosuid,nodev,noexec,size=64m",
    "--mount", f"type=bind,source={ws_parent},target=/data/workspace",
    "--mount", f"type=bind,source={scratch_parent},target=/data/scratch",
]
if mode == "demo":
    if not Path("/opt/epm/demo/dataset.json").is_file() or not Path("/opt/epm/demo/seed.py").is_file():
        raise SystemExit("Missing /opt/epm/demo/{dataset.json,seed.py} on host for synthetic demo seeding.")
    docker_cmd.extend(["--mount", "type=bind,source=/opt/epm/demo,target=/demo,readonly"])

init_code = """
import sys
from pathlib import Path
from app.modules.workspace.application.service import WorkspaceService
from app.platform.config import LocalConfig

mode, scratch_name = sys.argv[1], sys.argv[2]
ws_root = Path("/data/workspace/active")
scratch_dir = Path("/data/scratch") / scratch_name
scratch_dir.mkdir(mode=0o700, parents=True, exist_ok=True)
cfg_path = scratch_dir / "reinit-config.json"
svc = WorkspaceService(LocalConfig(config_path=cfg_path, workspace_path=ws_root))
svc.initialize(in_place=True)
if mode == "demo":
    from app.modules.hosted_admin.infrastructure.synthetic_seed import (
        canonical_seed_bundle_ref,
        seed_synthetic_workspace,
    )
    dataset = Path("/demo/dataset.json")
    seed_ref = canonical_seed_bundle_ref(dataset)
    seed_synthetic_workspace(
        ws_root,
        scratch_dir=scratch_dir,
        seed_bundle=seed_ref,
        dataset_path=dataset,
    )
print(f"Initialized workspace in {mode} mode.")
"""

docker_cmd.extend([
    "--pull", "never",
    "--entrypoint", "/opt/epm/venv/bin/python",
    image_ref, "-B", "-c", init_code, mode, scratch_reinit,
])
subprocess.run(docker_cmd, check=True)

# Preserve original workspaceId in workspace.json and property-management.sqlite.
new_ws_json = json.loads(ws_json_path.read_text(encoding="utf-8"))
new_ws_json["workspaceId"] = original_ws_id
ws_json_path.write_text(json.dumps(new_ws_json, indent=2) + "\n", encoding="utf-8")

db_path = active_dir / "database" / "property-management.sqlite"
conn = sqlite3.connect(str(db_path))
try:
    cur = conn.execute("UPDATE workspace_metadata SET workspace_id = ?", (original_ws_id,))
    if cur.rowcount != 1:
        raise SystemExit(f"Expected 1 workspace_metadata row, updated {cur.rowcount}.")
    conn.commit()
finally:
    conn.close()

shutil.rmtree(scratch_parent / scratch_reinit, ignore_errors=True)
subprocess.run(["chown", "-R", "65532:65532", str(ws_parent), str(scratch_parent)], check=True)
print(f"Preserved workspaceId={original_ws_id} and restored 65532:65532 ownership for {slug}.")
PY
}

recreate_operator_containers() {
  local image_ref="$1" target_slugs="$2"
  valid_image_ref "$image_ref" || die "Invalid Operator image ref: $image_ref"
  [[ -n "$target_slugs" ]] || die "Target operator slug list is required."

  say "Recreating Operator container(s) [$target_slugs] on $image_ref..."
  vm_python "$image_ref" "$target_slugs" <<'PY'
import json, subprocess, sys, time
from pathlib import Path

IMAGE = sys.argv[1]
RAW_SLUGS = sys.argv[2]
CENTRAL_UID = 65532
ENTRY_CMD = (
    "rm -f /run/epm-identity-sockets/*.sock; "
    "mkdir -m 700 /tmp/epm-identity-sockets; "
    "exec /opt/epm/venv/bin/python -B -m app.modules.hosted_access.infrastructure.operator_entry "
    "--configuration /control/deployment.json --tls-key /control/tls.key --tls-certificate /control/tls.pem"
)

reg = json.loads(Path("/etc/epm/pilot0-operators/registry.json").read_text(encoding="utf-8"))
operators = reg.get("operators", {})
if RAW_SLUGS == "ALL":
    selected = sorted(operators.items(), key=lambda kv: kv[1]["workspace_slug"])
else:
    wanted = {s.strip() for s in RAW_SLUGS.split(",") if s.strip()}
    selected = [
        (op_id, op)
        for op_id, op in sorted(operators.items(), key=lambda kv: kv[1]["workspace_slug"])
        if op["workspace_slug"] in wanted
    ]
    found = {op["workspace_slug"] for _, op in selected}
    missing = sorted(wanted - found)
    if missing:
        raise SystemExit(f"Unknown operator slug(s) not in registry.json: {', '.join(missing)}")

rolled = []
for op_id, op in selected:
    slug = op["workspace_slug"]
    ctr_name = f"epm-op-{slug}"
    net_name = f"epm-op-{slug}"
    op_ip = op["ip"]
    op_dir = f"/etc/epm/pilot0-operators/{op_id}"
    print(f"Recreating {ctr_name} ({op_id}, {op_ip})...")
    subprocess.run(["docker", "rm", "-f", ctr_name], check=False, capture_output=True)
    stale = Path(f"/run/epm-operator-sockets/{op_id}/{op_id}.sock")
    if stale.exists():
        stale.unlink()
    # IMPORTANT: Never pass --health-cmd; inherit exec-form HEALTHCHECK from Dockerfile.operator.
    subprocess.run([
        "docker", "run", "-d", "--name", ctr_name, "--restart", "unless-stopped",
        "--pull", "never", "--user", f"{CENTRAL_UID}:{CENTRAL_UID}",
        "--network", net_name, "--ip", op_ip,
        "--read-only", "--cap-drop", "ALL", "--security-opt", "no-new-privileges",
        "--tmpfs", "/tmp:rw,nosuid,nodev,noexec,size=32m",
        "--mount", f"type=bind,source={op_dir},target=/control,readonly",
        "--mount", f"type=bind,source=/srv/epm/data/workspace/{op_id},target=/data/workspace",
        "--mount", f"type=bind,source=/srv/epm/data/control/{op_id},target=/data/control",
        "--mount", f"type=bind,source=/srv/epm/data/scratch/{op_id},target=/data/scratch",
        "--mount", "type=bind,source=/run/epm-central-identity,target=/run/epm-central-identity",
        "--mount", f"type=bind,source=/run/epm-operator-sockets/{op_id},target=/run/epm-identity-sockets",
        "--entrypoint", "/bin/sh", IMAGE, "-ec", ENTRY_CMD,
    ], check=True)
    rolled.append(ctr_name)

deadline = time.monotonic() + 90.0
pending = set(rolled)
while pending and time.monotonic() < deadline:
    for ctr in list(pending):
        out = subprocess.check_output(
            ["docker", "inspect", "--format", "{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}", ctr],
            text=True,
        ).strip()
        state, _, health = out.partition("|")
        if state in {"exited", "dead"}:
            logs = subprocess.run(["docker", "logs", "--tail", "40", ctr], capture_output=True, text=True)
            raise SystemExit(f"{ctr} exited during startup (state={state}):\n{logs.stdout}\n{logs.stderr}")
        if state == "running" and health == "healthy":
            pending.remove(ctr)
    if pending:
        time.sleep(3)

if pending:
    print(subprocess.check_output(["docker", "ps", "-a", "--format", "{{.Names}} {{.Image}} {{.Status}}"], text=True))
    raise SystemExit(f"Timed out waiting for Docker (healthy): {', '.join(sorted(pending))}")

ready_check = (
    "import json, urllib.request; "
    "r = urllib.request.urlopen('http://127.0.0.1:8081/health/ready', timeout=5); "
    "body = r.read().decode(); "
    "assert r.status == 200 and json.loads(body).get('status') == 'ready', (r.status, body); "
    "print(r.status, body)"
)
for ctr in rolled:
    proc = subprocess.run(
        ["docker", "exec", ctr, "/opt/epm/venv/bin/python", "-B", "-c", ready_check],
        capture_output=True, text=True, check=False,
    )
    if proc.returncode != 0:
        raise SystemExit(f"Readiness check failed for {ctr}:\n{proc.stdout}\n{proc.stderr}")
    print(f"  {ctr} /health/ready -> {proc.stdout.strip()}")

print(subprocess.check_output(["docker", "ps", "--format", "{{.Names}} {{.Image}} {{.Status}}"], text=True))
PY
}

capture_operator_recovery_point() {
  local op_id="$1" slug="$2" image_ref="$3"
  valid_operator_id "$op_id" || die "Invalid operator_id: $op_id"
  valid_slug "$slug" || die "Invalid workspace slug: $slug"
  valid_image_ref "$image_ref" || die "Invalid image ref: $image_ref"

  say "Capturing fresh verified R2 + Cloud KMS recovery point for reinitialized $slug ($op_id)..."
  vm_python "$op_id" "$slug" "$image_ref" <<'PY'
import json, sqlite3, subprocess, sys, time
from pathlib import Path

op_id, slug, image_ref = sys.argv[1:4]
ctr_name = f"epm-op-{slug}"

inv = sqlite3.connect("/srv/epm/data/host/backup-proxy/inventory.sqlite")
try:
    row = inv.execute(
        "SELECT host_uid FROM operator_principals WHERE operator_id = ? AND retired_at IS NULL",
        (op_id,),
    ).fetchone()
finally:
    inv.close()
if not row:
    raise SystemExit(f"No active HOST_UID found in inventory.sqlite for operator {op_id}.")
host_uid = int(row[0])

dirs = [
    f"/srv/epm/data/workspace/{op_id}",
    f"/srv/epm/data/control/{op_id}",
    f"/srv/epm/data/scratch/{op_id}",
    f"/etc/epm/pilot0-operators/{op_id}",
]

backup_code = """
import time
from pathlib import Path
from app.modules.host_agent.infrastructure.backup_proxy import UnixBackupProxyClient
from app.modules.hosted_access.infrastructure.operator_entry import OperatorDeployment
from app.modules.hosted_access.infrastructure.shared_identity_entry import read_private
from app.modules.hosted_recovery.infrastructure.engine import ChunkedAeadBackupEngine
from app.modules.hosted_recovery.infrastructure.scheduler import WorkspaceBackupScheduler
from app.modules.workspace.infrastructure.hosted_recovery import HostedWorkspaceRecoveryService
from app.platform.sqlite_engine import create_sqlite_engine

cfg = OperatorDeployment.model_validate_json(read_private(Path("/control/deployment.json")))
b = cfg.binding
clock = lambda: time.time_ns() // 1_000_000
svc = HostedWorkspaceRecoveryService(
    recovery_engine=create_sqlite_engine(cfg.recovery_database),
    access_engine=create_sqlite_engine(cfg.access_database),
    backup_engine=ChunkedAeadBackupEngine(
        UnixBackupProxyClient(cfg.backup_proxy_socket, expected_proxy_uid=cfg.backup_proxy_uid)
    ),
    operator_id=b.scope.operator_id,
    workspace_id=b.scope.workspace_id,
    deployment_id=b.deployment_id,
    workspace_root=Path("/data/workspace"),
    scratch_root=cfg.scratch_directory,
    release_ref=cfg.release_ref,
    business_schema_revision=cfg.business_schema_revision,
    access_schema_revision=cfg.access_schema_revision,
    clock=clock,
)
sched = WorkspaceBackupScheduler(
    svc,
    deployment_id=b.deployment_id,
    operator_id=b.scope.operator_id,
    workspace_id=b.scope.workspace_id,
    clock=clock,
    nightly_interval_ms=1000,
    jitter_window_seconds=0,
)
ran = sched.run_once()
status = svc.read_protection_status()
print("RUN_ONCE:", ran, status)
if not ran:
    raise SystemExit("Recovery backup run_once returned False.")
"""

subprocess.run(["docker", "stop", ctr_name], check=True)
try:
    subprocess.run(["chown", "-R", f"{host_uid}:{host_uid}", *dirs], check=True)
    subprocess.run([
        "docker", "run", "--rm", "--network", "none", "--read-only",
        "--cap-drop", "ALL", "--security-opt", "no-new-privileges",
        "--user", f"{host_uid}:{host_uid}",
        "--tmpfs", "/tmp:rw,nosuid,nodev,noexec,size=32m",
        "--mount", f"type=bind,source=/etc/epm/pilot0-operators/{op_id},target=/control,readonly",
        "--mount", f"type=bind,source=/srv/epm/data/workspace/{op_id},target=/data/workspace",
        "--mount", f"type=bind,source=/srv/epm/data/control/{op_id},target=/data/control",
        "--mount", f"type=bind,source=/srv/epm/data/scratch/{op_id},target=/data/scratch",
        "--mount", "type=bind,source=/run/epm-backup-proxy,target=/run/epm-backup-proxy",
        "--pull", "never",
        "--entrypoint", "/opt/epm/venv/bin/python",
        image_ref, "-B", "-c", backup_code,
    ], check=True)
finally:
    subprocess.run(["chown", "-R", "65532:65532", *dirs], check=True)

subprocess.run(["docker", "start", ctr_name], check=True)
deadline = time.monotonic() + 90.0
while time.monotonic() < deadline:
    out = subprocess.check_output(
        ["docker", "inspect", "--format", "{{.State.Status}}|{{if .State.Health}}{{.State.Health.Status}}{{end}}", ctr_name],
        text=True,
    ).strip()
    if out == "running|healthy":
        break
    time.sleep(3)
else:
    raise SystemExit(f"{ctr_name} did not become healthy after backup restart.")

ready_check = (
    "import json, urllib.request; "
    "r = urllib.request.urlopen('http://127.0.0.1:8081/health/ready', timeout=5); "
    "body = r.read().decode(); "
    "assert r.status == 200 and json.loads(body).get('status') == 'ready', (r.status, body); "
    "print(r.status, body)"
)
subprocess.run(["docker", "exec", ctr_name, "/opt/epm/venv/bin/python", "-B", "-c", ready_check], check=True)

conn = sqlite3.connect("/srv/epm/data/host/h0312-identity/admin.sqlite")
try:
    row = conn.execute(
        "SELECT o.operator_id, o.workspace_id, r.protection_state, r.latest_point_ref, r.verified_at "
        "FROM operators o LEFT JOIN workspace_recovery_status r ON r.operator_id = o.operator_id "
        "WHERE o.operator_id = ?",
        (op_id,),
    ).fetchone()
    print("Admin workspace_recovery_status:", row)
finally:
    conn.close()
PY
}

run_canary_smoke_gate() {
  local target_url="$1" storage_state="${2:-}"
  [[ "$target_url" =~ ^https?://[A-Za-z0-9.:-]+$ ]] || die "Invalid smoke base URL: $target_url"
  if [[ "$target_url" == https://* ]]; then
    [[ -n "$storage_state" && -f "$storage_state" && -r "$storage_state" && -s "$storage_state" ]] ||
      die "Live canary smoke gate requires a readable Playwright storageState JSON file (EPM_SMOKE_STORAGE_STATE)."
  fi

  say "Running post-deploy smoke suite (SMOKE-01..SMOKE-05) against $target_url..."
  local status=0
  (
    cd "$application"
    if [[ -n "$storage_state" ]]; then
      EPM_SMOKE_BASE_URL="$target_url" EPM_SMOKE_STORAGE_STATE="$storage_state" npm run test:smoke
    else
      EPM_SMOKE_BASE_URL="$target_url" npm run test:smoke
    fi
  ) || status=$?

  if [[ "$status" != 0 ]]; then
    warn "Live canary smoke gate FAILED (exit $status)."
    warn "Rollout policy: HALT rollout to additional Operator containers."
    say "Inspect failure traces/screenshots in: $application/test-results/hosted-smoke/"
    say "To roll back the canary container, run:"
    say "  bash application/scripts/epm-pilot0-rollout.sh rollback"
    die "Canary smoke suite (SMOKE-01..SMOKE-05) failed."
  fi
  say "All 5 smoke checks (SMOKE-01..SMOKE-05) PASSED against $target_url."
}

roll_admin_service() {
  local target_spec="$1"
  local is_digest=false
  if valid_sha256_hex "$target_spec"; then
    is_digest=true
  elif valid_image_ref "$target_spec"; then
    is_digest=false
  else
    die "Invalid Admin target (expected 64-hex digest or epm-pilot0-admin:<tag>): $target_spec"
  fi

  say "Updating /opt/epm/h0312/run_identity.py MANIFEST and restarting epm-h03-identity.service..."
  vm_python "$target_spec" "$is_digest" "${HOST_SERVICES[@]}" <<'PY'
import datetime, os, re, shutil, subprocess, sys, time
from pathlib import Path

target_spec = sys.argv[1]
is_digest = sys.argv[2] == "true"
services = sys.argv[3:]

if is_digest:
    new_id = target_spec
else:
    raw = subprocess.check_output(
        ["docker", "image", "inspect", "--format", "{{.Id}}", target_spec], text=True
    ).strip()
    new_id = raw.removeprefix("sha256:")

if not re.fullmatch(r"[0-9a-f]{64}", new_id):
    raise SystemExit(f"Resolved Admin image ID is not 64 lowercase hex chars: {new_id!r}")
print(f"NEW_ID={new_id}")

identity_path = Path("/opt/epm/h0312/run_identity.py")
stamp = datetime.datetime.now(datetime.UTC).strftime("%Y%m%d")
backup_path = identity_path.with_name(f"run_identity.py.bak-{stamp}")
if backup_path.exists():
    stamp_full = datetime.datetime.now(datetime.UTC).strftime("%Y%m%d-%H%M%S")
    backup_path = identity_path.with_name(f"run_identity.py.bak-{stamp_full}")
shutil.copy2(identity_path, backup_path)
print(f"Backed up {identity_path} -> {backup_path}")

original = identity_path.read_text(encoding="utf-8")
updated, count = re.subn(
    r'^MANIFEST = "[0-9a-f]{64}"$',
    f'MANIFEST = "{new_id}"',
    original,
    count=1,
    flags=re.M,
)
if count != 1:
    raise SystemExit("MANIFEST line not found in /opt/epm/h0312/run_identity.py")

tmp_path = identity_path.with_name(f".run_identity.py.tmp.{os.getpid()}")
tmp_path.write_text(updated, encoding="utf-8")
os.chmod(tmp_path, identity_path.stat().st_mode & 0o777)
os.replace(tmp_path, identity_path)

for lineno, line in enumerate(identity_path.read_text(encoding="utf-8").splitlines(), start=1):
    if line.startswith("MANIFEST = "):
        print(f"{lineno}:{line}")

subprocess.run(["systemctl", "restart", "epm-h03-identity.service"], check=True)
time.sleep(20)

inactive = []
for svc in services:
    proc = subprocess.run(["systemctl", "is-active", svc], capture_output=True, text=True)
    state = proc.stdout.strip() or proc.stderr.strip()
    print(f"  {svc}: {state}")
    if proc.returncode != 0 or state != "active":
        inactive.append(f"{svc}={state}")

ps_out = subprocess.check_output(
    ["docker", "ps", "--format", "{{.Names}} {{.Image}} {{.Status}}"], text=True
)
print(ps_out)

journal = subprocess.check_output(
    ["journalctl", "-u", "epm-h03-identity.service", "--since", "2 minutes ago", "--no-pager"],
    text=True,
)
print(journal)

if inactive:
    raise SystemExit(f"One or more host services are not active: {', '.join(inactive)}")
if new_id[:12] not in ps_out:
    raise SystemExit(f"Running Admin container does not show new image prefix {new_id[:12]}.")
if "verify-shared" in journal and ("fail" in journal.lower() or "error" in journal.lower()):
    raise SystemExit("Detected verify-shared failure in epm-h03-identity.service journal.")
if "identitytoolkit bearer refreshed (600s)" not in journal:
    print("WARNING: 'identitytoolkit bearer refreshed (600s)' not seen in the last 2 minutes; inspect journal above.")
PY
}

