}

action_inspect() {
  stage "Select GCP Pilot 0 host"
  select_gcp_target

  stage "Inspect live Pilot 0 host state (read-only)"
  vm_python "${HOST_SERVICES[@]}" <<'PY'
import json, re, subprocess, sys
from pathlib import Path

services = sys.argv[1:]
print("=== Systemd services ===")
for svc in services:
    proc = subprocess.run(["systemctl", "is-active", svc], capture_output=True, text=True)
    print(f"  {svc}: {(proc.stdout or proc.stderr).strip()}")

print("\n=== Running containers ===")
print(subprocess.check_output(["docker", "ps", "--format", "{{.Names}} {{.Image}} {{.Status}}"], text=True).rstrip())

print("\n=== Admin MANIFEST ===")
identity = Path("/opt/epm/h0312/run_identity.py")
if identity.is_file():
    m = re.search(r'^MANIFEST = "([0-9a-f]{64})"$', identity.read_text(encoding="utf-8"), flags=re.M)
    print(f"  {m.group(0) if m else '(not found)'}")
else:
    print("  (run_identity.py missing)")

print("\n=== Registered Pilot 0 operators & /health/ready ===")
reg_path = Path("/etc/epm/pilot0-operators/registry.json")
if reg_path.is_file():
    reg = json.loads(reg_path.read_text(encoding="utf-8"))
    for op_id, op in sorted(reg.get("operators", {}).items(), key=lambda kv: kv[1]["workspace_slug"]):
        slug = op["workspace_slug"]
        ctr = f"epm-op-{slug}"
        probe = subprocess.run(
            [
                "docker", "exec", ctr, "/opt/epm/venv/bin/python", "-B", "-c",
                "import urllib.request; r=urllib.request.urlopen('http://127.0.0.1:8081/health/ready', timeout=3); print(r.status, r.read().decode())",
            ],
            capture_output=True, text=True, check=False,
        )
        ready = probe.stdout.strip() if probe.returncode == 0 else f"FAILED ({probe.stderr.strip()})"
        print(f"  {ctr} ({op_id}, {op['ip']}): {ready}")

print("\n=== Disk & memory ===")
print(subprocess.check_output(["df", "-h", "/", "/srv/epm/data"], text=True).rstrip())
print(subprocess.check_output(["free", "-h"], text=True).rstrip())
PY
  say "Read-only inspection complete. No host state was changed."
}

action_smoke() {
  stage "Select smoke target and Playwright storageState"
  ask EPM_CANARY_SLUG "Canary workspace slug [blank: $DEFAULT_CANARY_SLUG]:"
  EPM_CANARY_SLUG="${EPM_CANARY_SLUG:-$DEFAULT_CANARY_SLUG}"
  valid_slug "$EPM_CANARY_SLUG" || die "Invalid canary slug: $EPM_CANARY_SLUG"
  ask EPM_DOMAIN "Hosted domain [blank: $DEFAULT_DOMAIN]:"
  EPM_DOMAIN="${EPM_DOMAIN:-$DEFAULT_DOMAIN}"
  valid_domain "$EPM_DOMAIN" || die "Invalid domain: $EPM_DOMAIN"
  write_env EPM_CANARY_SLUG "$EPM_CANARY_SLUG"
  write_env EPM_DOMAIN "$EPM_DOMAIN"

  local default_url="https://${EPM_CANARY_SLUG}.${EPM_DOMAIN}"
  ask EPM_SMOKE_TARGET_URL "Smoke base URL [blank: $default_url]:"
  EPM_SMOKE_TARGET_URL="${EPM_SMOKE_TARGET_URL:-$default_url}"
  write_env EPM_SMOKE_TARGET_URL "$EPM_SMOKE_TARGET_URL"

  local storage_state=""
  if [[ "$EPM_SMOKE_TARGET_URL" == https://* ]]; then
    ask EPM_SMOKE_STORAGE_STATE "Authenticated Playwright storageState JSON path:"
    write_env EPM_SMOKE_STORAGE_STATE "$EPM_SMOKE_STORAGE_STATE"
    storage_state="$EPM_SMOKE_STORAGE_STATE"
  fi

  stage "Run post-deployment smoke suite (SMOKE-01..SMOKE-05)"
  run_canary_smoke_gate "$EPM_SMOKE_TARGET_URL" "$storage_state"
}

action_cleanup() {
  stage "Select GCP Pilot 0 host"
  select_gcp_target

  stage "Clean up temporary build artifacts"
  cleanup_build_artifacts
}

action_rollback() {
  stage "Select GCP host and rollback target"
  select_gcp_target
  if [[ -d "$snapshot_dir" ]]; then
    say "Saved pre-rollout snapshots in $snapshot_dir:"
    ls -1t "$snapshot_dir" 2>/dev/null | head -n 10 | sed 's/^/    /' || true
  fi
  ask EPM_ROLLBACK_SNAPSHOT "Snapshot JSON path to restore from [blank to enter digests manually]:"
  local op_target="" admin_target="" rollback_slugs=""
  if [[ -n "$EPM_ROLLBACK_SNAPSHOT" ]]; then
    [[ -f "$EPM_ROLLBACK_SNAPSHOT" && -r "$EPM_ROLLBACK_SNAPSHOT" ]] ||
      die "Snapshot file not readable: $EPM_ROLLBACK_SNAPSHOT"
    "$python_path" - "$EPM_ROLLBACK_SNAPSHOT" <<'PY'
import json, sys
from pathlib import Path
data = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
print(f"  Snapshot Admin MANIFEST: {data.get('admin_manifest') or '(none)'}")
for op in sorted(data.get("operators", {}).values(), key=lambda x: x["workspace_slug"]):
    print(f"  Snapshot Operator {op['workspace_slug']}: {op['image_id']} ({op['image_ref']})")
PY
    admin_target="$("$python_path" -c 'import json, sys; from pathlib import Path; print(json.loads(Path(sys.argv[1]).read_text(encoding="utf-8")).get("admin_manifest", ""))' "$EPM_ROLLBACK_SNAPSHOT")"
  fi

  stage "Roll back Pilot 0 Operator container(s)"
  if confirm "Roll back Operator container(s)?"; then
    if [[ -n "$EPM_ROLLBACK_SNAPSHOT" ]]; then
      say "Rolling back each selected Operator to its exact snapshot image_id."
      ask EPM_ROLLBACK_SLUGS "Comma-separated operator slugs to roll back, or ALL [blank: ALL]:"
      rollback_slugs="${EPM_ROLLBACK_SLUGS:-ALL}"
      valid_slug_list "$rollback_slugs" || die "Invalid operator slug list: $rollback_slugs"
      local snap_rows=() row _op_id op_slug prev_image
      while IFS= read -r row; do
        [[ -n "$row" ]] && snap_rows+=("$row")
      done < <(list_snapshot_operators "$EPM_ROLLBACK_SNAPSHOT")
      for row in "${snap_rows[@]+"${snap_rows[@]}"}"; do
        IFS=$'\t' read -r _op_id op_slug prev_image <<< "$row"
        [[ -n "$op_slug" && -n "$prev_image" ]] || continue
        if [[ "$rollback_slugs" == "ALL" || ",$rollback_slugs," == *",$op_slug,"* ]]; then
          confirm "Recreate epm-op-$op_slug on $prev_image?" || continue
          recreate_operator_containers "$prev_image" "$op_slug"
        fi
      done
    else
      ask EPM_ROLLBACK_OP_IMAGE "Previous Operator image ref or sha256:... ID:"
      valid_image_ref "$EPM_ROLLBACK_OP_IMAGE" || die "Invalid Operator image ref."
      ask EPM_ROLLBACK_SLUGS "Comma-separated operator slugs to roll back, or ALL [blank: ALL]:"
      rollback_slugs="${EPM_ROLLBACK_SLUGS:-ALL}"
      valid_slug_list "$rollback_slugs" || die "Invalid operator slug list: $rollback_slugs"
      confirm "Recreate Operator container(s) [$rollback_slugs] on $EPM_ROLLBACK_OP_IMAGE?" ||
        die "Operator rollback cancelled."
      recreate_operator_containers "$EPM_ROLLBACK_OP_IMAGE" "$rollback_slugs"
    fi
  else
    say "Skipped Operator container rollback."
  fi

  stage "Roll back Pilot 0 Admin (epm-h03-identity.service)"
  if confirm "Roll back Admin MANIFEST and restart epm-h03-identity.service?"; then
    if [[ -z "$admin_target" ]]; then
      ask EPM_ROLLBACK_ADMIN_MANIFEST "Previous Admin 64-hex MANIFEST digest (without sha256:):"
      admin_target="$EPM_ROLLBACK_ADMIN_MANIFEST"
    else
      say "Using snapshot Admin MANIFEST: $admin_target"
    fi
    valid_sha256_hex "$admin_target" || die "Expected 64 lowercase hex characters for Admin MANIFEST."
    confirm "Restore MANIFEST=$admin_target in /opt/epm/h0312/run_identity.py and restart?" ||
      die "Admin rollback cancelled."
    roll_admin_service "$admin_target"
  else
    say "Skipped Admin rollback."
  fi
  note "If a workspace was reinitialized in Section 3.1, restore active.bak-<YYYYMMDD> manually before resuming writes."
}

action_rollout() {
  local reinit_entries=()

  stage "Select GCP destination, release tag, and review source"
  for tool in git gcloud npm tar uv shasum; do need "$tool"; done
  select_gcp_target

  local today_tag="pilot0-$(date +%Y%m%d)-release"
  ask EPM_RELEASE_TAG "Release tag (pilot0-YYYYMMDD-<label>) [e.g. $today_tag]:"
  valid_release_tag "$EPM_RELEASE_TAG" ||
    die "Release tag must match pilot0-YYYYMMDD-<label> (lowercase letters, digits, dots, underscores, hyphens)."
  write_env EPM_RELEASE_TAG "$EPM_RELEASE_TAG"

  ask EPM_CANARY_SLUG "Canary operator slug [blank: $DEFAULT_CANARY_SLUG]:"
  EPM_CANARY_SLUG="${EPM_CANARY_SLUG:-$DEFAULT_CANARY_SLUG}"
  valid_slug "$EPM_CANARY_SLUG" || die "Invalid canary slug: $EPM_CANARY_SLUG"
  write_env EPM_CANARY_SLUG "$EPM_CANARY_SLUG"

  ask EPM_DOMAIN "Hosted domain [blank: $DEFAULT_DOMAIN]:"
  EPM_DOMAIN="${EPM_DOMAIN:-$DEFAULT_DOMAIN}"
  valid_domain "$EPM_DOMAIN" || die "Invalid domain: $EPM_DOMAIN"
  write_env EPM_DOMAIN "$EPM_DOMAIN"

  cd "$repo"
  local source_commit dirty
  source_commit="$(git rev-parse HEAD)"
  dirty="$(git status --porcelain)"
  say "Source commit: $source_commit"
  if [[ -n "$dirty" ]]; then
    warn "Uncommitted changes present in repository:"
    git status --short | sed 's/^/    /'
    confirm "Proceed with uncommitted working tree changes?" || die "Commit or stash changes first."
  else
    confirm "Roll out commit $source_commit as $EPM_RELEASE_TAG to $EPM_INSTANCE?" ||
      die "Rollout cancelled."
  fi

  if confirm "Run pre-rollout local Docker smoke gate (http://localhost:18802) before packaging?"; then
    run_canary_smoke_gate "http://localhost:18802" ""
  else
    note "Skipping local pre-rollout smoke gate (ensure local verification already passed)."
  fi

  stage "Fetch pinned dependency lockfile & wheelhouse (Section 1.1)"
  fetch_agent_bundle

  stage "Build frontend bundles, package OCI contexts & upload (Sections 1.2–1.3)"
  if confirm "Build frontend bundles, package AMD64 contexts, and upload to $EPM_INSTANCE?"; then
    package_and_upload_contexts
  else
    warn "Skipped local packaging/upload — assuming /tmp/epm-contexts.tar.gz is already on $EPM_INSTANCE."
  fi

  stage "Build immutable AMD64 OCI images on $EPM_INSTANCE (Section 2)"
  if confirm "Build offline AMD64 images epm-pilot0-operator:$EPM_RELEASE_TAG and epm-pilot0-admin:$EPM_RELEASE_TAG?"; then
    build_remote_images
  else
    warn "Skipped remote docker build — verifying existing tagged images on $EPM_INSTANCE..."
    local inspect_out op_id admin_id
    inspect_out="$(vm_ssh --command="
printf 'EPM_IMG_OPERATOR=%s\n' \"\$(sudo docker image inspect --format '{{.Id}}' epm-pilot0-operator:${EPM_RELEASE_TAG})\"
printf 'EPM_IMG_ADMIN=%s\n' \"\$(sudo docker image inspect --format '{{.Id}}' epm-pilot0-admin:${EPM_RELEASE_TAG})\"
sudo docker image inspect --format '{{.RepoTags}} {{.Id}}' epm-pilot0-operator:${EPM_RELEASE_TAG} epm-pilot0-admin:${EPM_RELEASE_TAG}
")"
    printf '%s\n' "$inspect_out"
    op_id="$(printf '%s\n' "$inspect_out" | sed -n 's/^EPM_IMG_OPERATOR=//p' | tail -n1)"
    admin_id="$(printf '%s\n' "$inspect_out" | sed -n 's/^EPM_IMG_ADMIN=//p' | tail -n1)"
    valid_image_ref "$op_id" || die "Existing Operator image epm-pilot0-operator:$EPM_RELEASE_TAG not found on $EPM_INSTANCE."
    valid_image_ref "$admin_id" || die "Existing Admin image epm-pilot0-admin:$EPM_RELEASE_TAG not found on $EPM_INSTANCE."
    EPM_OPERATOR_IMAGE_ID="$op_id"
    EPM_ADMIN_IMAGE_ID="$admin_id"
    write_env EPM_OPERATOR_IMAGE_ID "$EPM_OPERATOR_IMAGE_ID"
    write_env EPM_ADMIN_IMAGE_ID "$EPM_ADMIN_IMAGE_ID"
  fi

  stage "Snapshot live state & optional SQLite schema reinit (Section 3.1)"
  snapshot_file="$snapshot_dir/${EPM_RELEASE_TAG}-$(date -u +%Y%m%dT%H%M%SZ).json"
  capture_pre_rollout_snapshot "$snapshot_file"
  say "Saved pre-rollout rollback snapshot: $snapshot_file"
  note "validate_latest_schema enforces exact DDL/CHECK equality on startup."
  local snap_rows=() row op_id op_slug _prev_img reinit_mode
  while IFS= read -r row; do
    [[ -n "$row" ]] && snap_rows+=("$row")
  done < <(list_snapshot_operators "$snapshot_file")

  if confirm "Did this release modify application/database/sqlite-migrations/versions/0001_initial_schema.py (requires workspace reinit)?"; then
    for row in "${snap_rows[@]+"${snap_rows[@]}"}"; do
      IFS=$'\t' read -r op_id op_slug _prev_img <<< "$row"
      [[ -n "$op_id" && -n "$op_slug" ]] || continue
      if confirm "Back up and reinitialize workspace for $op_slug ($op_id)?"; then
        ask EPM_REINIT_MODE "Mode for $op_slug (demo = synthetic-demo-v1, empty = empty workspace):"
        reinit_mode="$EPM_REINIT_MODE"
        [[ "$reinit_mode" == "demo" || "$reinit_mode" == "empty" ]] ||
          die "Choose 'demo' or 'empty' for $op_slug."
        reinit_operator_workspace "$op_id" "$op_slug" "$reinit_mode" "epm-pilot0-operator:${EPM_RELEASE_TAG}"
        reinit_entries+=("${op_id}:${op_slug}")
      fi
    done
  else
    say "No business SQLite schema reinitialization selected."
  fi

  stage "Roll canary Operator ($EPM_CANARY_SLUG) & run live smoke gate (Section 3.2)"
  confirm "Recreate canary container epm-op-$EPM_CANARY_SLUG on epm-pilot0-operator:$EPM_RELEASE_TAG?" ||
    die "Canary rollout cancelled."
  recreate_operator_containers "epm-pilot0-operator:${EPM_RELEASE_TAG}" "$EPM_CANARY_SLUG"

  local entry r_op_id r_slug
  for entry in "${reinit_entries[@]+"${reinit_entries[@]}"}"; do
    r_op_id="${entry%%:*}"
    r_slug="${entry#*:}"
    if [[ "$r_slug" == "$EPM_CANARY_SLUG" ]]; then
      capture_operator_recovery_point "$r_op_id" "$r_slug" "epm-pilot0-operator:${EPM_RELEASE_TAG}"
    fi
  done

  local canary_url="https://${EPM_CANARY_SLUG}.${EPM_DOMAIN}"
  say "Mandatory post-deploy smoke gate (SMOKE-01..SMOKE-05) on $canary_url."
  note "All 5 checks must pass before rolling remaining Pilot 0 Operator containers."
  ask EPM_SMOKE_STORAGE_STATE "Authenticated Demo A Playwright storageState JSON path:"
  write_env EPM_SMOKE_STORAGE_STATE "$EPM_SMOKE_STORAGE_STATE"
  run_canary_smoke_gate "$canary_url" "$EPM_SMOKE_STORAGE_STATE"

  stage "Roll remaining Pilot 0 Operator containers (Section 3.2)"
  local remaining_slugs=""
  while IFS=$'\t' read -r _op_id op_slug _prev_img; do
    [[ -n "$op_slug" && "$op_slug" != "$EPM_CANARY_SLUG" ]] || continue
    if [[ -n "$remaining_slugs" ]]; then
      remaining_slugs+=",${op_slug}"
    else
      remaining_slugs="$op_slug"
    fi
  done < <(list_snapshot_operators "$snapshot_file")

  if [[ -n "$remaining_slugs" ]]; then
    say "Remaining Pilot 0 operators: $remaining_slugs"
    confirm "Recreate remaining Operator containers ($remaining_slugs) on epm-pilot0-operator:$EPM_RELEASE_TAG?" ||
      die "Remaining Operator rollout cancelled (canary remains on $EPM_RELEASE_TAG)."
    recreate_operator_containers "epm-pilot0-operator:${EPM_RELEASE_TAG}" "$remaining_slugs"
    for entry in "${reinit_entries[@]+"${reinit_entries[@]}"}"; do
      r_op_id="${entry%%:*}"
      r_slug="${entry#*:}"
      if [[ "$r_slug" != "$EPM_CANARY_SLUG" ]]; then
        capture_operator_recovery_point "$r_op_id" "$r_slug" "epm-pilot0-operator:${EPM_RELEASE_TAG}"
      fi
    done
  else
    say "No additional Pilot 0 Operator containers beyond canary ($EPM_CANARY_SLUG)."
  fi

  stage "Roll live Pilot 0 Admin (epm-h03-identity.service) & verify (Section 4)"
  note "Gotcha: qualified_releases is immutable — never UPDATE rows; INSERT a new release_id only when admitting new operators."
  if confirm "Update /opt/epm/h0312/run_identity.py MANIFEST to epm-pilot0-admin:$EPM_RELEASE_TAG and restart?"; then
    roll_admin_service "epm-pilot0-admin:${EPM_RELEASE_TAG}"
  else
    SKIPPED+=("Admin rollout (epm-h03-identity.service -> epm-pilot0-admin:$EPM_RELEASE_TAG)")
    warn "Skipped Admin rollout."
  fi

  say "Verify live rollout in your browser (hard-refresh with Cmd+Shift+R):"
  step "Open https://admin.${EPM_DOMAIN}/, click Refresh source on Demo A, and confirm Source access and Free usage reflect live state."
  step "Open ${canary_url}/ and confirm the updated Operator UI loads cleanly."
  if confirm "Open Admin and Canary URLs in your browser now?"; then
    open_url "https://admin.${EPM_DOMAIN}/"
    open_url "${canary_url}/"
  fi
  confirm "Have live Admin (Refresh source) and Operator browser checks passed?" ||
    die "Browser verification not confirmed. Temporary build artifacts retained; inspect or run rollback."

  stage "Clean up temporary build artifacts (Section 5)"
  cleanup_build_artifacts
  say "Rollout summary:"
  say "  Release tag:       $EPM_RELEASE_TAG"
  say "  Operator image ID: ${EPM_OPERATOR_IMAGE_ID:-epm-pilot0-operator:$EPM_RELEASE_TAG}"
  say "  Admin image ID:    ${EPM_ADMIN_IMAGE_ID:-epm-pilot0-admin:$EPM_RELEASE_TAG}"
  say "  Rollback snapshot: $snapshot_file"
}

main() {
  if [[ "${1:-}" == --help || "${1:-}" == -h ]]; then
    cat <<'EOF'
Usage: bash application/scripts/epm-pilot0-rollout.sh [rollout|inspect|smoke|rollback|cleanup]

Interactive Pilot 0 GCP rollout wizard following docs/hosting/operations/pilot0-release-rollout.md:
  rollout   Full end-to-end macOS -> epm-h02-host release rollout with mandatory canary smoke gate
  inspect   Read-only check of live host services, containers, /health/ready, and Admin MANIFEST
  smoke     Run the 5-check post-deploy smoke suite (SMOKE-01..SMOKE-05) against a target URL
  rollback  Restore Operator containers and/or Admin MANIFEST from a saved pre-rollout snapshot
  cleanup   Remove temporary build artifacts on epm-h02-host and optional local macOS staging
EOF
    return
  fi
  [[ $# -le 1 ]] || die "Too many arguments. Use --help for usage."
  [[ "$(uname -s)" == Darwin ]] || die "Run this Pilot 0 rollout wizard from macOS."
  [[ -t 0 && -t 1 ]] || die "Run interactively in a terminal."

  unset PYTHONPATH PYTHONHOME
  umask 077

  local repo application state_dir snapshot_dir python_path snapshot_file="" action="${1:-}"
  repo="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)"
  application="$repo/application"
  python_path="$(resolve_python)"
  state_dir="$HOME/Library/Application Support/EPM/pilot0-rollout"
  snapshot_dir="$state_dir/snapshots"
  mkdir -p "$state_dir" "$snapshot_dir"
  ENV_FILE="$state_dir/rollout.env"
  touch "$ENV_FILE"
  chmod 600 "$ENV_FILE"

  if [[ -z "$action" ]]; then
    say "Choose action: rollout, inspect, smoke, rollback, cleanup."
    ask EPM_PILOT0_ACTION "Action [blank: rollout]:"
    action="${EPM_PILOT0_ACTION:-rollout}"
  fi

  case "$action" in
    rollout) TOTAL_STAGES=9 ;;
    inspect) TOTAL_STAGES=2 ;;
    smoke) TOTAL_STAGES=2 ;;
    rollback) TOTAL_STAGES=3 ;;
    cleanup) TOTAL_STAGES=2 ;;
    *) die "Unknown action: $action (choose rollout, inspect, smoke, rollback, or cleanup)." ;;
  esac

  trap 'failed "$?"' ERR
  trap 'die "Interrupted. No automatic rollback was performed; inspect current host state."' INT TERM

  banner "EPM · Pilot 0 GCP $action wizard"
  case "$action" in
    rollout) action_rollout ;;
    inspect) action_inspect ;;
    smoke) action_smoke ;;
    rollback) action_rollback ;;
    cleanup) action_cleanup ;;
  esac
  finish
}

main "$@"
